immobiliardarlehen_wechselkurswarnschwelle <- function(wert_zum_vertragskurs=NULL,wert_zum_vergleichskurs=NULL,warnfolge_bereits_ausgeloest=NULL,einordnungsnachweis=NULL) {
 basis <- .geld(wert_zum_vertragskurs); aktuell <- .geld(wert_zum_vergleichskurs)
 .wahrheitswert(warnfolge_bereits_ausgeloest,'warnfolge_bereits_ausgeloest'); .text(einordnungsnachweis,'einordnungsnachweis')
 if(.vergleichen(basis,.bruch(0))<=0) .fehler('wert_zum_vertragskurs','Positiver Vertragskurs-Vergleichswert erforderlich.')
 grenze <- .multiplizieren(basis,.bruch(6,5)); veraenderung <- .dividieren(.subtrahieren(aktuell,basis),basis)
 wert <- list(relative_wertaenderung=.bruchteile(veraenderung),zwanzigprozent_grenzwert=.bruchteile(grenze),neuausloesungsschwelle_ueberschritten=.vergleichen(aktuell,grenze)>0,fortdauerschwelle_erreicht=.vergleichen(aktuell,grenze)>=0,numerische_warnbedingung=if(warnfolge_bereits_ausgeloest) .vergleichen(aktuell,grenze)>=0 else .vergleichen(aktuell,grenze)>0)
 eingaben <- list(wert_zum_vertragskurs=wert_zum_vertragskurs,wert_zum_vergleichskurs=wert_zum_vergleichskurs,warnfolge_bereits_ausgeloest=warnfolge_bereits_ausgeloest,einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,'quote_und_landeswaehrung','BGB_IMMOBILIARDARLEHEN_WECHSELKURSWARNSCHWELLE',eingaben,list(list(operation='Relative Werta\u0308nderung bestimmen; erste Ausl\u00f6sung strikt \u00fcber6/5 Basiswert, bereits ausgel\u00f6ste Folge bis zum Unterschreiten dieser Grenze.')),eingaben)
 ergebnis$hinweise <- list("Nur numerischer Vergleich nach \u00a7493 Absatz4 Satz1/Satz2 Nummer4 im qualifizierten Fremdw\u00e4hrungs-/entsprechenden Einkommensw\u00e4hrungsfall. Beide Werte m\u00fcssen denselben aktuellen Restbetrag oder dieselbe regelm\u00e4\u00dfige Rate in gleicher Landesw\u00e4hrung zu Vertrags- bzw. Vergleichskurs darstellen; Werte gegebenenfalls mit immobiliardarlehen_wechselkursrechnung vorbereiten. Bei bereits ausgel\u00f6ster Folge h\u00e4lt genau20% die numerische Fortdauergrenze ein, l\u00f6st aber erstmals keine Folge aus. Restbetrag und Raten gemeinsam fachlich ber\u00fccksichtigen, sofern beide ma\u00dfgeblich sind. Keine automatische Bestimmung regelm\u00e4\u00dfiger Informationsabst\u00e4nde, kein Versand und kein vollst\u00e4ndiger Informationstatbestand. Nullvergleichsbasis au\u00dferhalb dieser relativen Rechnung.")
 ergebnis
}
